export function CloseButton({
  label = "{{label}}",
  size = "{{size}}",
  bg = "{{bg}}",
  radius = {{radius}},
  disabled = {{disabled}},
}) {
  const pad = size === "sm" ? 5 : size === "lg" ? 11 : 8;
  return (
    <button
      type="button"
      aria-label={label}
      disabled={disabled}
      style={{
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        padding: pad,
        borderRadius: radius,
        border: "none",
        background: "transparent",
        color: "#241430",
        cursor: disabled ? "not-allowed" : "pointer",
        opacity: disabled ? 0.4 : 1,
      }}
      onMouseOver={(e) => (e.currentTarget.style.color = bg)}
      onMouseOut={(e) => (e.currentTarget.style.color = "#241430")}
    >
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
        <path d="M6 6l12 12M18 6L6 18" />
      </svg>
    </button>
  );
}
